<StageBars
  title="App orders"
  stages={[{ id: "opened", label: "Opened the app" }, { id: "basket", label: "Added to basket" }, { id: "paid", label: "Paid" }]}
  periods={[{ id: "week", label: "This week", values: [2480, 1164, 611] }]}
/>
